const fleet = [
  { id: "dvp24-01", name: "Trạm nghiền", slave: 1 },
  { id: "dvp24-02", name: "Trạm trộn", slave: 2 },
  { id: "dvp24-03", name: "Băng tải chính", slave: 3 },
  { id: "dvp24-04", name: "Máy nén khí", slave: 4 },
  { id: "dvp24-05", name: "Trạm bơm nước", slave: 5 },
  { id: "dvp24-06", name: "Tủ điện phụ", slave: 6 }
];
return [fleet.map(function (d) {
  return {
    topic: "plc/" + d.id + "/config",
    payload: { id: d.id, name: d.name, slave: d.slave, cycle: 300 },
    qos: 1,
    retain: true
  };
})];

const id = (msg.topic || "").split("/")[1];
if (!id) return null;
const devs = flow.get("devices") || {};
let raw = msg.payload;
if (Buffer.isBuffer(raw)) raw = raw.toString();
if (!raw || raw === "") {
  delete devs[id];
  flow.set("devices", devs);
  return [{ topic: "plc/" + id + "/status", payload: "", qos: 1, retain: true }];
}
let cfg;
try { cfg = typeof raw === "object" ? raw : JSON.parse(raw); } catch (e) { return null; }
if (!cfg || typeof cfg.id !== "string") return null;
devs[id] = {
  id: id,
  name: String(cfg.name || id).slice(0, 32),
  slave: Number(cfg.slave) || 1,
  cycle: Number(cfg.cycle) || 300
};
flow.set("devices", devs);
return [{ topic: "plc/" + id + "/status", payload: "online", qos: 1, retain: true }];

const now = Date.now();
const tick = (context.get("tick") || 0) + 1;
context.set("tick", tick);
const devs = flow.get("devices") || {};
const out = [];
for (const id of Object.keys(devs)) {
  const d = devs[id];
  const cycle = Number(d.cycle) || 300;
  const div = Math.max(1, Math.round(cycle / 100));
  const phase = (Number(d.slave) || 1) % div;
  if (tick % div !== phase) continue;
  const t = now / 1000;
  const s = Number(d.slave) || 1;
  const ys = flow.get("y:" + id) || {};
  const seq = (flow.get("seq:" + id) || 0) + 1;
  flow.set("seq:" + id, seq);
  out.push({
    topic: "plc/" + id + "/telemetry",
    qos: 1,
    payload: {
      device: id,
      ts: now,
      seq: seq,
      quality: "GOOD",
      X0: (Math.floor(t) + s) % 4 === 0 ? 1 : 0,
      X1: (Math.floor(t) + s) % 6 === 0 ? 1 : 0,
      X2: 0,
      X3: 1,
      X4: 0,
      X5: 0,
      X6: 0,
      X7: 0,
      Y0: ys.Y0 ? 1 : 0,
      Y1: ys.Y1 ? 1 : 0,
      Y2: ys.Y2 ? 1 : 0,
      Y3: ys.Y3 ? 1 : 0,
      Y4: 0,
      Y5: 0,
      Y6: 0,
      Y7: 0,
      M0: 1,
      M1: 0,
      M2: 0,
      M3: 0,
      D100: 900 + s * 40 + Math.round(120 * Math.sin(t / 10 + s)),
      D101: Math.round((20 + 2 * Math.sin(t / 7 + s) + s * 0.5) * 10) / 10,
      D102: 400 + s * 10 + (Math.floor(t) % 100)
    }
  });
}
return out.length ? [out] : null;

const id = (msg.topic || "").split("/")[1];
if (!id) return null;
let c = msg.payload;
if (Buffer.isBuffer(c)) c = c.toString();
try { c = typeof c === "object" ? c : JSON.parse(c); } catch (e) { return null; }
if (!c || c.action !== "write" || typeof c.target !== "string") return null;
const key = "y:" + id;
const ys = flow.get(key) || {};
ys[c.target] = c.value ? 1 : 0;
flow.set(key, ys);
return {
  topic: "plc/" + id + "/ack",
  qos: 1,
  payload: {
    id: c.id || null,
    device: id,
    ok: true,
    ts: Date.now(),
    target: c.target,
    value: c.value === undefined ? null : c.value
  }
};

const HEADER = "time,device,seq,quality,X0,X1,X2,X3,X4,X5,X6,X7,Y0,Y1,Y2,Y3,Y4,Y5,Y6,Y7,M0,M1,M2,M3,D100,D101,D102";
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
try { p = typeof p === "object" ? p : JSON.parse(p); } catch (e) { return null; }
if (!p || typeof p !== "object") return null;
const id = (msg.topic || "").split("/")[1] || p.device || "";
if (!id) return null;
const ts = Number(p.ts) || Date.now();
const d = new Date(ts);
const pad = n => (n < 10 ? "0" : "") + n;
const day = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
const hour = pad(d.getHours());
const name = "telemetry-" + day + "-" + hour + ".csv";
const time = day + " " + hour + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds()) + "." + String(d.getMilliseconds()).padStart(3, "0");
const bit = v => (v === true || v === 1 || v === "1") ? 1 : 0;
const num = v => (v === null || v === undefined || v === "") ? "" : (typeof v === "number" ? v : Number(v));
const cols = [time, id, num(p.seq), p.quality === undefined || p.quality === null ? "" : p.quality];
for (let i = 0; i < 8; i++) cols.push(bit(p["X" + i]));
for (let i = 0; i < 8; i++) cols.push(bit(p["Y" + i]));
for (let i = 0; i < 4; i++) cols.push(bit(p["M" + i]));
cols.push(num(p.D100), num(p.D101), num(p.D102));
const file = "/logs/" + name;
try {
  if (!fs.existsSync(file)) fs.writeFileSync(file, HEADER + "\n");
  fs.appendFileSync(file, cols.join(",") + "\n");
} catch (e) {
  node.error("Ghi CSV thất bại: " + e.message);
  return null;
}
if (flow.get("csvName") === name) return null;
flow.set("csvName", name);
return { topic: "plc/log/file", payload: { name: name, url: "/logs/" + name }, qos: 1, retain: true };
